/bin/bash -lc "node --input-type=module <<'EOF'
import { spawnSync } from 'node:child_process';

const cases = [
  ['--help'],
  [],
  ['--a', '1'],
  ['--a', '1', '--b', '{}'],
  ['--a=1', '--b={}'],
  ['--a', '--b', '--b', '{}'],
  ['--a', '-1', '--b', '{}'],
  ['--a', '1', '--b', '{}', '--c', '2'],
  ['--a', '1', '--bb', '{}'],
  ['--help=foo'],
  ['-hfoo'],
  ['--a', '{\"x\":1,\"y\":2}', '--b', '{\"additionalProperties\":false,\"properties\":{\"x\":{}}}'],
  ['--a', '{\"ab\":1,\"ac\":2}', '--b', '{\"propertyNames\":{\"pattern\":\""'^ab$"}}'"'],
  ['--a', '[1,2,3]', '--b', '{\"items\":[{\"type\":\"integer\"}],\"additionalItems\":false}'],
  ['--a', '[1,2,3]', '--b', '{\"contains\":{\"type\":\"string\"}}'],
  ['--a', '1', '--b', '{\"anyOf\":[{\"type\":\"string\"},{\"minimum\":2}]}'],
  ['--a', '1', '--b', '{\"allOf\":[{\"minimum\":2},{\"maximum\":0}]}'],
  ['--a', '1', '--b', '{\"oneOf\":[{\"type\":\"number\"},{\"const\":1}]}'],
  ['--a', '{\"x\":1}', '--b', '{\"dependencies\":{\"x\":[\"y\",\"z\"]}}'],
  ['--a', '{\"x\":1}', '--b', '{\"dependencies\":{\"x\":{\"required\":[\"y\"],\"properties\":{\"x\":{\"type\":\"string\"}}}}}'],
  ['--a', '\"x\"', '--b', '{\"if\":{\"const\":\"x\"},\"then\":{\"maxLength\":0},\"else\":{\"type\":\"number\"}}'],
  ['--a', '1', '--b', 'false'],
  ['--a', '2.0', '--b', '{\"type\":\"integer\"}'],
  ['--a', '1.0', '--b', '{\"enum\":[1]}'],
  ['--a', '[1.0,1]', '--b', '{\"uniqueItems\":true}'],
  ['--a', '0.3', '--b', '{\"multipleOf\":0.1}'],
  ['--a', '1', '--b', '{\""'$ref":"#/definitions/int","type":"string","definitions":{"int":{"type":"integer"}}}'"'],
];

function run(command, args) {
  return spawnSync(command, args, { encoding: 'utf8' });
}

let mismatches = 0;
for (const args of cases) {
  const expected = run('/workspace/dataset/test5_executable', args);
  const actual = run('node', ['/output/test5.mjs', ...args]);

  const normalize = (text) => text
    .replaceAll('test5_executable', 'test5.mjs');

  const expectedOut = normalize(expected.stdout);
  const expectedErr = normalize(expected.stderr);
  const actualOut = actual.stdout;
  const actualErr = actual.stderr;

  if (expected.status "'!== actual.status || expectedOut !== actualOut || expectedErr !== actualErr) {
    mismatches += 1;
    console.log('"'Mismatch for args:', JSON.stringify(args));
    console.log('expected status:', expected.status, 'actual status:', actual.status);
    console.log('expected stdout:', JSON.stringify(expectedOut));
    console.log('actual stdout  :', JSON.stringify(actualOut));
    console.log('expected stderr:', JSON.stringify(expectedErr));
    console.log('actual stderr  :', JSON.stringify(actualErr));
  }
}

if (mismatches === 0) {
  console.log('All sampled cases matched.');
}
EOF"

